<?php
/* Phase 333: canonical PNG repair after WordPress image scaling. */
add_action('init',function(){
 if(get_option('bhc_catalog_image_snowa_microwave_repair_v333'))return;
 @ini_set('memory_limit','768M');$base=__DIR__.'/';$upload=wp_upload_dir();$map=['BHC-SNOWA-SMO-FM30GCW'=>['model'=>'smo-fm30gcw','file'=>'snowa-smo-fm30gcw-v332-source.png'],'BHC-SNOWA-SMO-FM32GCS'=>['model'=>'smo-fm32gcs','file'=>'snowa-smo-fm32gcs-v332-source.png']];
 foreach($map as $sku=>$it){$id=wc_get_product_id_by_sku($sku);if(!$id)continue;$src=$base.$it['file'];if(!is_readable($src))continue;$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,true);$im=@imagecreatefrompng($src);if(!$im)continue;$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=(int)round($w*$scale);$nh=(int)round($h*$scale);$out=imagecreatetruecolor($nw,$nh);imagealphablending($out,false);imagesavealpha($out,true);$c=imagecolorallocatealpha($out,0,0,0,127);imagefilledrectangle($out,0,0,$nw,$nh,$c);imagecopyresampled($out,$im,0,0,0,0,$nw,$nh,$w,$h);$rel='bhc-image-references/snowa-'.$it['model'].'-v333-repair.png';$dst=trailingslashit($upload['basedir']).$rel;wp_mkdir_p(dirname($dst));@unlink($dst);imagepng($out,$dst,6);imagedestroy($out);imagedestroy($im);$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>'Snowa '.$it['model'].' transparent 4K canonical','post_status'=>'inherit'],$dst,$id);if(!$aid)continue;update_post_meta($aid,'_wp_attached_file',$rel);update_post_meta($aid,'_wp_attachment_metadata',['width'=>$nw,'height'=>$nh,'file'=>$rel,'sizes'=>[],'image_meta'=>[]]);set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','generated_4k_transparent_verified');}
 update_option('bhc_catalog_image_snowa_microwave_repair_v333',['count'=>count($map),'at'=>current_time('mysql')],false);
},333);
